const C=window.SITE_CONFIG,app=document.querySelector('#app');let properties=[],saved;try{saved=JSON.parse(localStorage.getItem('haven-saved')||'[]');if(!Array.isArray(saved))saved=[]}catch{saved=[]}let deal='Buy';const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const money=p=>new Intl.NumberFormat('en-US',{style:'currency',currency:C.currency,maximumFractionDigits:0}).format(p.price);const price=p=>`${money(p)}${p.deal==='Rent'?' <small>/ month</small>':''}`;const options=(values,selected)=>values.map(v=>`<option ${v===selected?'selected':''}>${esc(v)}</option>`).join('');
function toast(t){const e=document.querySelector('#toast');e.textContent=t;e.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>e.style.display='none',3500)}function updateCount(){document.querySelector('#saved-count').textContent=saved.length}function toggleSave(id){saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];try{localStorage.setItem('haven-saved',JSON.stringify(saved))}catch{}updateCount();document.querySelectorAll(`[data-save="${id}"]`).forEach(b=>{b.classList.toggle('selected',saved.includes(id));b.textContent=saved.includes(id)?'♥':'♡';b.setAttribute('aria-pressed',saved.includes(id))});if(location.hash.startsWith('#/saved'))render()}
function card(p){return `<article class="card"><a class="card-image" href="#/property/${p.id}" aria-label="View ${esc(p.name)}"><img src="${p.image}" alt="Illustrative ${p.type.toLowerCase()} interior for ${esc(p.name)}" loading="lazy"></a><span class="badge">For ${p.deal==='Buy'?'sale':'rent'} · ${p.type}</span><button class="heart ${saved.includes(p.id)?'selected':''}" data-save="${p.id}" aria-label="Save ${esc(p.name)}" aria-pressed="${saved.includes(p.id)}">${saved.includes(p.id)?'♥':'♡'}</button><div class="card-body"><div class="location">${esc(p.area)} · ${esc(p.city)}</div><a href="#/property/${p.id}"><h3>${esc(p.name)}</h3></a><div class="price">${price(p)}</div><div class="specs"><span>${p.beds?p.beds+' beds':'Commercial'}</span><span>${p.baths} baths</span><span>${p.size.toLocaleString()} sq ft</span></div></div></article>`}
function searchForm(q=new URLSearchParams(),home=false){return `<div class="search-wrap ${home?'':'listing-search'}">${home?`<div class="tabs" role="group" aria-label="Listing purpose"><button type="button" data-deal="Buy" class="active">Buy a property</button><button type="button" data-deal="Rent">Rent a property</button></div>`:''}<form id="search-form" class="search-form"><div class="field"><label for="location">Location or property</label><input id="location" name="q" placeholder="City, neighbourhood or property name" value="${esc(q.get('q')||'')}" list="cities"><datalist id="cities">${['Dubai','Mumbai','Bengaluru','Goa'].map(x=>`<option value="${x}">`).join('')}</datalist></div><div class="field"><label for="type">Property type</label><select name="type" id="type">${options(['Any property','House','Apartment','Villa','Office'],q.get('type')||'Any property')}</select></div><div class="field"><label for="budget">Maximum budget (USD)</label><select name="max" id="budget">${[['','Any budget'],['3000','$3,000'],['5000','$5,000'],['500000','$500,000'],['1000000','$1,000,000'],['3000000','$3,000,000']].map(([v,l])=>`<option value="${v}" ${v===q.get('max')?'selected':''}>${l}</option>`).join('')}</select></div><button class="btn" type="submit">Search properties <span>↗</span></button></form></div>`}
function cta(){return `<section class="cta"><div><div class="eyebrow">Your next chapter starts here</div><h2>Let’s find a place<br>that feels like you.</h2></div><a class="btn" href="#/contact">Speak with an advisor ↗</a></section>`}
function home(){deal='Buy';return `<section class="hero"><div class="hero-copy"><div class="eyebrow">A world of exceptional possibilities</div><h1>A place for<br>what’s next.</h1><p>Discover considered homes and inspiring spaces.<br>Find the one that feels entirely yours.</p></div><div class="hero-index">01 — THE ART OF LIVING WELL</div></section>${searchForm(new URLSearchParams(),true)}<section class="section"><div class="section-head"><div><div class="eyebrow">THE HAVEN COLLECTION</div><h2>Remarkable by nature.</h2></div><a class="text-link" href="#/properties">View all properties ↗</a></div><div class="grid">${properties.slice(0,3).map(card).join('')}</div></section><section class="section" style="padding-top:0"><div class="section-head"><div><div class="eyebrow">FIND YOUR WAY OF LIVING</div><h2>Spaces for every chapter.</h2></div></div><div class="collection"><a href="#/properties?type=House"><img src="assets/property-3.jpg" alt="Contemporary residence" loading="lazy"><div class="caption"><div class="eyebrow">Room to make memories</div><h3>Extraordinary homes <span>↗</span></h3></div></a><a href="#/properties?type=Office"><img src="assets/property-2.jpg" alt="Open contemporary office" loading="lazy"><div class="caption"><div class="eyebrow">Space for your ambition</div><h3>Inspired workspaces <span>↗</span></h3></div></a></div></section><section class="story"><img src="assets/property-5.jpg" alt="Carefully designed living space" loading="lazy"><div class="story-copy"><div class="eyebrow">A MORE PERSONAL APPROACH</div><h2>Property is personal.<br>We keep it that way.</h2><p>More than square footage and an address. It’s how a space makes you feel, and the possibilities it opens. Explore at your own pace, then connect with an advisor when you’re ready.</p><a class="text-link" href="#/about">Discover our approach ↗</a></div></section>${cta()}`}
function listing(q,isSaved=false){deal=q.get('deal')||'Any';let rows=properties.filter(p=>(!isSaved||saved.includes(p.id))&&(deal==='Any'||p.deal===deal)&&(!q.get('type')||q.get('type')==='Any property'||p.type===q.get('type'))&&(!q.get('max')||p.price<=+q.get('max'))&&(!q.get('beds')||p.beds>=+q.get('beds'))&&(!q.get('q')||`${p.name} ${p.city} ${p.area} ${p.type}`.toLowerCase().includes(q.get('q').trim().toLowerCase())));if(q.get('sort')==='low')rows.sort((a,b)=>a.price-b.price);if(q.get('sort')==='high')rows.sort((a,b)=>b.price-a.price);return `<div class="page-title"><a class="back" href="#/">Home / ${isSaved?'Saved properties':'Explore'}</a><h1>${isSaved?'Your saved places.':'Find your next place.'}</h1><p>${isSaved?'A little closer to finding the one. Saved on this browser.':'Explore our illustrative collection of homes and workspaces across four destinations.'}</p></div>${isSaved?'':searchForm(q)}<section class="section" style="padding-top:35px"><div class="toolbar"><span>${rows.length} ${rows.length===1?'property':'properties'} ${isSaved?'saved':'available'} · Demo listings</span>${isSaved?'':`<div class="filters"><label>Purpose <select data-filter="deal">${options(['Any','Buy','Rent'],deal)}</select></label><label>Bedrooms <select data-filter="beds"><option value="">Any beds</option>${[1,2,3,4,5].map(n=>`<option value="${n}" ${q.get('beds')==n?'selected':''}>${n}+ beds</option>`).join('')}</select></label><label>Sort <select data-filter="sort"><option value="">Featured</option><option value="low" ${q.get('sort')==='low'?'selected':''}>Price: low to high</option><option value="high" ${q.get('sort')==='high'?'selected':''}>Price: high to low</option></select></label><a class="text-link" href="#/properties">Reset</a></div>`}</div><div class="grid">${rows.length?rows.map(card).join(''):`<div class="empty"><h2>${isSaved?'Keep your favourites close.':'No properties found.'}</h2><p>${isSaved?'Tap the heart on a property to save it here.':'Try a different location, property type or budget.'}</p><a class="btn" href="#/properties">Explore all properties ↗</a></div>`}</div></section>`}
function detail(id){const p=properties.find(x=>x.id===id);if(!p)return `<section class="section empty"><h1>Property not found</h1><a class="btn" href="#/properties">Browse properties</a></section>`;return `<div class="page-title"><a class="back" href="#/properties">← Back to properties</a><div class="section-head"><div><div class="eyebrow" style="margin-top:25px">${p.type} · For ${p.deal==='Buy'?'sale':'rent'} · Demo listing</div><h1>${esc(p.name)}</h1><p>${esc(p.area)}, ${p.city}</p></div><button class="btn light" data-save="${p.id}" aria-pressed="${saved.includes(p.id)}">${saved.includes(p.id)?'♥':'♡'}</button></div></div><div class="detail-gallery">${p.gallery.map((src,i)=>`<button data-photo="${i}" data-property="${p.id}" aria-label="Open property photo ${i+1}"><img src="${src}" alt="Illustrative property photo ${i+1}">${i===0?'<span>▦ View gallery · 3 photos</span>':''}</button>`).join('')}</div><section class="section detail-layout"><div><div class="eyebrow">A SPACE TO CALL YOUR OWN</div><h2>Considered in every detail.</h2><div class="facts"><div><strong>${p.beds||'Office'}</strong><small>${p.beds?'Bedrooms':'Property type'}</small></div><div><strong>${p.baths}</strong><small>Bathrooms</small></div><div><strong>${p.size.toLocaleString()}</strong><small>Square feet</small></div><div><strong>${p.deal==='Buy'?'Sale':'Rent'}</strong><small>Availability type</small></div></div><p>${esc(p.description)}</p><p>This sample listing illustrates how your property information can be presented. Specifications, imagery, pricing and availability must be replaced and verified before commercial use.</p><h2>Features & amenities</h2><div class="amenities">${p.amenities.map(a=>`<span>✓ &nbsp;${a}</span>`).join('')}</div><h2>The neighbourhood</h2><p>${p.area}, ${p.city}. A location with convenient connections to everyday essentials, dining and local destinations. Exact address and verified map coordinates can be added with your real listing data.</p><p class="demo-note">Property reference: HV-${p.id.padStart(4,'0')} · Illustrative stock photography; not a verified property.</p></div><aside class="contact-card"><div class="eyebrow">YOUR NEXT CHAPTER</div><h2 class="price">${price(p)}</h2><p>Interested in this property? Connect with an advisor to discuss details or arrange a viewing.</p><a class="btn" href="#/contact?property=${p.id}">Enquire about this property ↗</a><button class="btn light" data-wa="${p.id}">Chat on WhatsApp ↗</button><p class="demo-note">Demo mode: WhatsApp opens a shareable enquiry draft. Set your business number in config.js to route directly to your agency.</p></aside></section><section class="section" style="padding-top:0"><div class="section-head"><h2>You may also like.</h2><a class="text-link" href="#/properties">View all ↗</a></div><div class="grid">${properties.filter(x=>x.id!==id&&(x.city===p.city||x.type===p.type)).slice(0,3).map(card).join('')}</div></section>`}
function contact(q){const p=properties.find(x=>x.id===q.get('property'));return `<section class="section contact-layout"><div><div class="eyebrow">LET’S START A CONVERSATION</div><h1 style="font-size:52px">Good things begin<br>with a hello.</h1><div class="prose"><p>Tell us what you have in mind. Whether you’re finding a home, exploring a workspace or planning your next move, start with what matters to you.</p><h2>Prefer to chat?</h2><p>Create your enquiry and continue on WhatsApp. You’ll review the message before sending it.</p><button class="btn light" data-wa="${p?.id||''}">Open WhatsApp ↗</button><p class="demo-note">Demonstration only. No form submissions are stored or sent to an agency. WhatsApp uses a draft until you configure your business number.</p></div></div><form id="enquiry-form"><h2 style="margin:0">Tell us about your plans.</h2><div class="field"><label for="name">Your name *</label><input name="name" id="name" required maxlength="100" autocomplete="name"></div><div class="field"><label for="email">Email address *</label><input type="email" name="email" id="email" required autocomplete="email"></div><div class="field"><label for="interest">Property of interest</label><select name="property" id="interest"><option value="">General enquiry</option>${properties.map(x=>`<option value="${x.id}" ${p?.id===x.id?'selected':''}>${esc(x.name)} — ${x.city}</option>`).join('')}</select></div><div class="field"><label for="message">How can we help? *</label><textarea name="message" id="message" required maxlength="2000" placeholder="Tell us your preferred location, budget and timing…"></textarea></div><label style="font-size:12px;line-height:1.8"><input type="checkbox" required> I understand this creates a WhatsApp draft and have read the <a href="#/privacy" style="text-decoration:underline">privacy information</a>.</label><button class="btn">Continue to WhatsApp ↗</button><small style="color:var(--muted)">You choose whether to send. Nothing is submitted here.</small></form></section>`}
function about(){return `<section class="section prose"><div class="eyebrow">THE HAVEN APPROACH</div><h1 style="font-size:54px">An exceptional place.<br>A personal experience.</h1><img src="assets/property-0.jpg" style="width:100%;max-height:400px;object-fit:cover" alt="Modern home"><h2>Start with how you want to live.</h2><p>Your search begins with your priorities: the neighbourhood, the space, the daily rhythm. HAVEN is a fictional real estate brand created to demonstrate a calm, thoughtful way to discover properties.</p><h2>Explore. Discover. Connect.</h2><p>Search homes and offices by location, type and budget. Save the places that catch your eye. View the details, explore the imagery, and prepare an enquiry to start a conversation.</p><h2>A foundation for your agency.</h2><p>This demo can be rebranded with your business name, real listings, verified details and contact number. Property data is separate from the interface, ready for a future secure Airtable integration.</p><a class="btn" href="#/properties">Explore the collection ↗</a></section>${cta()}`}
function privacy(){return `<section class="section prose"><h1 style="font-size:44px">Privacy & demo information</h1><p>This is an independent demonstration website. HAVEN, its agency details, listing names, prices and specifications are fictional examples. Photographs are illustrative stock images and do not represent verified listings. There is no affiliation with Sotheby’s International Realty.</p><h2>Data in this demo</h2><p>Saved property IDs are stored in your browser’s local storage. Enquiry form information is used only to compose a WhatsApp link when you choose to continue. There is no database submission, account creation, analytics or Airtable connection in this demo.</p><h2>External services</h2><p>WhatsApp opens only when you click an enquiry action and is governed by its own terms. Google Fonts may receive standard network information when fonts load. All listing photographs are bundled locally.</p><h2>Before a commercial launch</h2><p>Replace the branding, verify listings and image rights, configure your agency’s contact number, connect your data service securely and supply a privacy policy suited to your business and jurisdiction.</p><button class="btn light" id="clear-saved">Clear saved properties</button></section>`}
function whatsapp(id,extra=''){const p=properties.find(x=>x.id===id),msg=`Hello ${C.brand}, ${p?`I’m interested in ${p.name} in ${p.area}, ${p.city} (HV-${p.id.padStart(4,'0')}). Please share details and viewing availability.`:'I’d like help finding a property.'}${extra?'\n\n'+extra:''}`;let num=C.whatsappNumber.replace(/\D/g,'');window.open(num?`https://wa.me/${num}?text=${encodeURIComponent(msg)}`:`https://api.whatsapp.com/send?text=${encodeURIComponent(msg)}`,'_blank','noopener,noreferrer');if(!num)toast('Demo enquiry draft opened. Choose a recipient in WhatsApp.')}
function render(){let hash=location.hash.slice(1)||'/',[path,query]=hash.split('?'),q=new URLSearchParams(query);app.innerHTML=path==='/'?home():path==='/properties'?listing(q):path==='/saved'?listing(q,true):path.startsWith('/property/')?detail(path.split('/')[2]):path==='/contact'?contact(q):path==='/about'?about():path==='/privacy'?privacy():`<section class="section empty"><h1>Page not found</h1><a class="btn" href="#/">Back to home</a></section>`;document.title=`${path.startsWith('/property/')?properties.find(p=>p.id===path.split('/')[2])?.name||'Property':path==='/properties'?'Explore properties':path==='/contact'?'Get in touch':'A place for what’s next'} | ${C.brand}`;window.scrollTo(0,0);updateCount();window.initMotion();const sf=document.querySelector('#search-form');if(sf)sf.onsubmit=e=>{e.preventDefault();let params=new URLSearchParams(new FormData(sf));if(params.get('type')==='Any property')params.delete('type');for(const [k,v]of [...params])if(!v.trim())params.delete(k);if(deal!=='Any')params.set('deal',deal);location.hash='/properties?'+params};document.querySelectorAll('[data-filter]').forEach(el=>el.onchange=()=>{q.set(el.dataset.filter,el.value);location.hash='/properties?'+q});const ef=document.querySelector('#enquiry-form');if(ef)ef.onsubmit=e=>{e.preventDefault();const d=new FormData(ef);whatsapp(d.get('property'),`Name: ${d.get('name')}\nEmail: ${d.get('email')}\n${d.get('message')}`)}}
document.addEventListener('click',e=>{const save=e.target.closest('[data-save]');if(save)toggleSave(save.dataset.save);const wa=e.target.closest('[data-wa]');if(wa)whatsapp(wa.dataset.wa);const tab=e.target.closest('[data-deal]');if(tab){deal=tab.dataset.deal;document.querySelectorAll('[data-deal]').forEach(t=>t.classList.toggle('active',t===tab))}const photo=e.target.closest('[data-photo]');if(photo){const p=properties.find(x=>x.id===photo.dataset.property);let idx=+photo.dataset.photo;const show=()=>{document.querySelector('#lightbox-img').src=p.gallery[idx];document.querySelector('#photo-count').textContent=`${idx+1} / ${p.gallery.length}`};document.querySelector('#prev-photo').onclick=()=>{idx=(idx+2)%3;show()};document.querySelector('#next-photo').onclick=()=>{idx=(idx+1)%3;show()};show();document.querySelector('#lightbox').showModal()}if(e.target.id==='clear-saved'){saved=[];try{localStorage.removeItem('haven-saved')}catch{}updateCount();toast('Saved properties cleared')}});window.addEventListener('hashchange',render);document.querySelectorAll('.brand').forEach(e=>{e.firstChild.textContent=C.brand;e.querySelector('span').textContent=C.tagline});document.querySelector('#year').textContent=new Date().getFullYear();fetch(C.propertiesUrl).then(r=>{if(!r.ok)throw Error('Loading failed');return r.json()}).then(p=>{properties=p;render()}).catch(()=>app.innerHTML='<section class="error"><h1>Unable to load properties</h1><p>Please refresh the page. For local use, start the included development server.</p><button onclick="location.reload()">Try again</button></section>');
